changeSet.sql:
create or alter procedure api.DeleteTagTypes
	@resourceId int,
	@uids dbo.UidTable readonly
as
begin
	set nocount on;
	declare @success bit = 0;

	declare @tagUids dbo.UidTable;
	insert into @tagUids
		select	o.Uid 
		from	Tag o
				inner join TagType t on t.ID = o.TagTypeId
				inner join @uids u on u.Uid = t.uid;

	begin try
		begin tran

		update	t
		set		t.State = 3 -- deleted
		from	TagType t 
				inner join @uids u on u.Uid = t.uid;

		exec @success = api.DeleteTags @resourceId, @tagUids;

		if @success = 1
		begin
			commit;
		end
		else
		begin
			rollback;
		end
	end try
	begin catch
		rollback;
	end catch

	return @success;
end
